$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';require_once $root.'/app/StoryMediaService.php';require_once $root.'/app/UserProfileService.php';AuthService::boot();$user=AuthService::requireLogin();$gid=(int)($_GET['game']??$_POST['game_id']??0);if($gid<1){header('Location: ./');exit;}
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');if($action==='claim')LobbyService::claimCharacter($gid,(int)$user['user_id'],(int)$_POST['character_id']);if($action==='release')LobbyService::releaseCharacter($gid,(int)$user['user_id']);if($action==='invite_player'){$emails=array_values(array_unique(array_filter(array_map(static fn($e)=>strtolower(trim($e)),preg_split('/[\s,;]+/',(string)($_POST['emails']??''))))));if(!$emails){$_SESSION['lobby_notice']='Enter at least one email address.';}else{$extra=count($emails)>20;$emails=array_slice($emails,0,20);$sent=[];$links=[];$problems=[];foreach($emails as$email){try{$invite=AuthService::createGameInvitation($email,$gid,(int)$user['user_id']);if($invite['sent'])$sent[]=$email;else$links[]=$email.': '.$invite['url'];}catch(Throwable$e){$problems[]=$email.' ('.$e->getMessage().')';}}$parts=[];if($sent)$parts[]='Invitations sent to '.implode(', ',$sent).' from accounts@toinky.com.';if($links)$parts[]='Email delivery was unavailable for '.count($links).'. Share these secure links: '.implode(' ',$links);if($problems)$parts[]='Could not invite: '.implode('; ',$problems);if($extra)$parts[]='Only the first 20 addresses were processed.';$_SESSION['lobby_notice']=implode(' ',$parts);}}if($action==='invite_friends'){$friends=UserProfileService::acceptedFriends((int)$user['user_id']);$allowed=[];foreach($friends as$friend)$allowed[(int)$friend['friend_user_id']]=$friend;foreach(array_unique(array_map('intval',(array)($_POST['friend_user_ids']??[])))as$friendId)if(isset($allowed[$friendId]))AuthService::createGameInvitation((string)$allowed[$friendId]['email'],$gid,(int)$user['user_id']);$_SESSION['lobby_notice']='Friend invitations sent.';}if($action==='delete_lobby'){LobbyService::deleteLobby($gid,(int)$user['user_id']);header('Location: ./');exit;}if($action==='start')LobbyService::startGame($gid,(int)$user['user_id']);header('Location: '.($action==='start'?'play.php':'lobby.php').'?game='.$gid);exit;}catch(Throwable$e){$error=$e->getMessage();}}
try{$state=LobbyService::lobbyState($gid,(int)$user['user_id']);}catch(Throwable$e){http_response_code(403);die(e($e->getMessage()));}if($state['game']['status']!=='LOBBY'){header('Location: play.php?game='.$gid);exit;}
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function lobby_duration(int $seconds):string{if($seconds%86400===0)return intdiv($seconds,86400).' '.(intdiv($seconds,86400)===1?'Day':'Days');if($seconds%60===0)return intdiv($seconds,60).' Minutes';return$seconds.' Seconds';}
$mine=null;foreach($state['players']as$p)if((int)$p['user_id']===(int)$user['user_id'])$mine=(int)($p['character_id']??0);$aiChars=[];foreach($state['characters']as$c)if(empty($c['user_id']))$aiChars[]=!empty($c['mystery_character'])?'Mystery Character':(string)$c['name'];$notice=(string)($_SESSION['lobby_notice']??'');unset($_SESSION['lobby_notice']);$inviteLink=AuthService::baseUrl().'/?view=join&code='.rawurlencode((string)$state['game']['join_code']);$characterImages=StoryMediaService::characterImagesForPlot((int)$state['game']['plot_id']);$friends=$state['is_host']?UserProfileService::acceptedFriends((int)$user['user_id']):[];$storyTeaser=trim((string)($state['game']['scenario_text']??''));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Game Lobby · Toinky</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#eef2f7}*{box-sizing:border-box}body{margin:0}.bar{background:#111827;color:#fff;padding:15px 22px}.barin,.shell{max-width:1100px;margin:auto}.barin{display:flex;justify-content:space-between;align-items:center}.bar a{color:#fff}.shell{padding:28px 20px}.top,.players{display:flex;gap:16px;justify-content:space-between;align-items:center;flex-wrap:wrap}.code{font:900 34px ui-monospace,monospace;letter-spacing:.18em;background:#fff;border:2px dashed #B58E46;border-radius:13px;padding:12px 18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:15px;margin-top:18px}.card{background:#fff;border:2px solid #dce3ec;border-radius:15px;padding:18px}.card.taken{opacity:.48;filter:grayscale(.55)}.card.mine{border-color:#B58E46;box-shadow:0 0 0 3px #ead9b8}.btn{border:0;border-radius:9px;background:#B58E46;color:#1C242B;padding:10px 14px;font:inherit;font-weight:800;cursor:pointer}.btn.alt{background:#fff;color:#273043;border:1px solid #cbd5e1}.btn.start{background:#66715C;color:#fff;font-size:17px;padding:13px 20px}.btn.danger{background:#fff1f2;color:#9f1239;border:1px solid #fecdd3}.error{background:#fee2e2;color:#991b1b;padding:12px;border-radius:10px;margin-bottom:15px}.muted{color:#64748b}.people{background:#fff;border-radius:13px;padding:16px;margin:20px 0}.person{display:inline-flex;align-items:center;gap:8px;margin:5px 8px 5px 0;padding:7px 10px;background:#f1f5f9;border-radius:8px}.character-portrait{width:100%;height:230px;object-fit:cover;border-radius:10px;margin-bottom:12px}.player-avatar{width:32px;height:32px;object-fit:cover;border-radius:50%}.story-context{background:#fffaf0;border-left:4px solid #B58E46;padding:14px 16px;margin:18px 0}.header-links{display:flex;gap:14px}.friend-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;margin:12px 0}@media(max-width:600px){.shell{padding:20px 14px}.code{font-size:27px;width:100%;text-align:center}.grid{grid-template-columns:1fr}.people form{display:grid;gap:8px}.people input[type=email]{width:100%}.character-portrait{height:auto;aspect-ratio:4/3}}
</style><link rel="stylesheet" href="assets/toinky-theme.css"><link rel="stylesheet" href="assets/toinky-signed-header.css"></head><body><?php require_once __DIR__.'/_signed_header.php';render_signed_header($user,'Lobby',(string)$state['game']['title']);?><main class="shell"><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="people"><?=e($notice)?></div><?php endif;?><div class="top"><div><h1><?=e($state['game']['title'])?></h1><p class="muted"><?=e($state['game']['genre'])?> · Hosted by <?=e($state['game']['host_name'])?> · <?=e(lobby_duration((int)($state['game']['play_duration_seconds']??$state['game']['duration_seconds'])))?></p><p>Share this code with the other players, or send them the invite link:</p></div><div class="code"><?=e($state['game']['join_code'])?></div><button type="button" class="btn alt" id="copy-join-code" data-code="<?=e($state['game']['join_code'])?>" style="margin-top:8px">Copy code</button><button type="button" class="btn alt" id="copy-invite-link" data-link="<?=e($inviteLink)?>" style="margin-top:8px">Copy invite link</button></div>
<section class="story-context"><b>Setting: <?=e($state['game']['setting_name'])?></b><?php if($storyTeaser!==''):?><p><?=e($storyTeaser)?></p><?php endif;?></section><section class="people"><b>Players in Lobby</b><div><?php foreach($state['players']as$p):?><span class="person"><?php if(!empty($p['profile_image_path'])):?><img class="player-avatar" src="<?=e($p['profile_image_path'])?>" alt=""><?php endif;?><?=e($p['display_name'])?><?=empty($p['character_id'])?(((int)$p['user_id']===(int)$state['game']['host_user_id'])?' · hosting':' · choosing…'):' · ready'?></span><?php endforeach;?></div></section>
<section class="people"><h2>Voice Narrator</h2><p class="muted">The narrator reads the story aloud as it unfolds. Pick your voice and choose whether to hear it &mdash; your choice is saved just for you. The good-quality voice downloads in the background while you wait here, so it is ready when the game starts (a one-time download, then it is saved on your device).</p><label style="display:block;margin:8px 0"><input type="checkbox" id="lobby-narrator-enable"> Read the story aloud</label><label style="display:block;margin:8px 0">Voice <select id="lobby-narrator-voice" style="padding:8px;border:1px solid #cbd5e1;border-radius:8px;max-width:100%"></select></label><p class="muted" id="lobby-narrator-status" style="margin:8px 0 0">Preparing narrator voice&hellip;</p></section>
<h2>Choose Your Character</h2><p class="muted">A claimed character becomes unavailable to everyone else within a few seconds. Every unclaimed character becomes autonomous.<?php if($state['is_host']):?> As the host, playing is optional &mdash; you can run the story night without claiming a character.<?php endif;?></p><div class="grid"><?php foreach($state['characters']as$c):if(($c['actor_type']??'')==='NPC')continue;$taken=!empty($c['user_id'])&&(int)$c['user_id']!==(int)$user['user_id'];$isMine=(int)($c['user_id']??0)===(int)$user['user_id'];$isMystery=!empty($c['mystery_character']);?><article class="card <?=$taken?'taken':''?> <?=$isMine?'mine':''?>"><?php if(!$isMystery&&isset($characterImages[$c['role_code']])):?><img class="character-portrait" src="<?=e($characterImages[$c['role_code']]['file_path'])?>" alt="<?=e($characterImages[$c['role_code']]['alt_text'])?>"><?php endif;?><h3><?=e($isMystery?'Mystery Character':$c['name'])?></h3><?php if($isMystery):?><p class="muted">Identity and details revealed when the story begins.</p><?php else:?><p><?=e($c['description'])?></p><?php endif;?><?php if($taken):?><b>Chosen by <?=e($c['player_name'])?></b><?php elseif($isMine):?><b>Your Character</b><form method="post" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="release"><button class="btn alt">Choose Someone Else</button></form><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="claim"><input type="hidden" name="character_id" value="<?=(int)$c['character_id']?>"><button class="btn">Choose <?=e($isMystery?'Mystery Character':$c['name'])?></button></form><?php endif;?></article><?php endforeach;?></div>
<?php if($state['is_host']):?><section class="people"><h2>Invite Players by Email</h2><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="invite_player"><label>Email addresses <textarea name="emails" required rows="3" placeholder="One per line, or separate with commas" style="padding:10px;border:1px solid #cbd5e1;border-radius:8px;vertical-align:top;min-width:260px"></textarea></label> <button class="btn">Send Invitations</button></form><?php if($friends):?><h3>Invite Friends</h3><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="invite_friends"><div class="friend-grid"><?php foreach($friends as$friend):?><label><input type="checkbox" name="friend_user_ids[]" value="<?=(int)$friend['friend_user_id']?>"> <?=e($friend['display_name'])?><?=!empty($friend['label_text'])?' · '.e($friend['label_text']):''?></label><?php endforeach;?></div><button class="btn">Invite Selected Friends</button></form><?php endif;?></section><section class="people"><h2>Host Controls</h2><p>Start once every joined player has chosen a character. You don&rsquo;t need to claim one yourself.</p><form method="post" id="start-form"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="start"><button class="btn start" id="start-btn"<?php if($aiChars):?> type="button"<?php endif;?>>Start the Game</button><?php if($aiChars):?><div id="ai-confirm" style="display:none;margin-top:14px"><p style="margin:0 0 8px"><b>The following characters will be played by AI:</b></p><ul style="margin:0 0 12px;padding-left:20px"><?php foreach($aiChars as$aiName):?><li><?=e($aiName)?></li><?php endforeach;?></ul><button class="btn start" type="submit">Proceed to Game?</button> <button class="btn alt" type="button" id="ai-cancel">Not Yet</button></div><?php endif;?></form><?php if($state['can_delete']):?><form method="post" style="margin-top:14px" data-confirm="Delete this empty lobby?"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="delete_lobby"><button class="btn danger">Delete Lobby</button></form><?php else:?><div style="margin-top:14px"><button class="btn danger" disabled title="Delete is available once every player has released their character.">Delete Lobby</button><p class="muted" style="font-size:13px;margin:6px 0 0">Delete is available once every player has released their character.</p></div><?php endif;?></section><?php else:?><section class="people"><b>Waiting for the host to start…</b></section><?php endif;?></main>
<script>let fingerprint=<?=json_encode([$state['game']['status'],array_map(fn($p)=>[(int)$p['user_id'],(int)($p['character_id']??0)],$state['players'])])?>;setInterval(async()=>{try{const r=await fetch('lobby-state.php?game=<?=$gid?>',{cache:'no-store'});if(!r.ok)return;const s=await r.json();if(s.status!=='LOBBY'){location.href='play.php?game=<?=$gid?>';return;}if(JSON.stringify(s.fingerprint)!==JSON.stringify(fingerprint))location.reload();}catch(e){}},2000);const sb=document.getElementById('start-btn'),ac=document.getElementById('ai-confirm');if(sb&&ac){sb.addEventListener('click',()=>{sb.style.display='none';ac.style.display='block';});document.getElementById('ai-cancel').addEventListener('click',()=>{ac.style.display='none';sb.style.display='';});}function bindCopy(id,attr,label){const b=document.getElementById(id);if(!b)return;b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset[attr]);b.textContent='Copied!';}catch(e){b.textContent='Copy failed';}setTimeout(()=>{b.textContent=label;},2000);});}bindCopy('copy-join-code','code','Copy code');bindCopy('copy-invite-link','link','Copy invite link');</script><script src="assets/toinky-narrator-lobby.js"></script><?php require __DIR__.'/_confirm_modal.php';?></body></html>
